  "factions[faction-hxh-zodiacs].structure[0].members[11].role": "Sanglier, puis Léorio",
  "factions[faction-hxh-zoldyck].localizedName": "Famille Zoldik",
  "factions[faction-hxh-zoldyck].description": "La famille d'assassins professionnels la plus redoutée du monde, qui réside sur le mont Kukuroo.",
  "factions[faction-hxh-zoldyck].longDescription": "Des générations de tueurs entraînés dès la naissance. Parmi ses membres figurent le patriarche Zeno, le père Silva, la mère Kikyo et les enfants, dont Kirua.",
  "factions[faction-hxh-zoldyck].structure[0].name": "Famille",
  "factions[faction-hxh-zoldyck].structure[0].members[0].role": "arrière-grand-père",
  "factions[faction-hxh-zoldyck].structure[0].members[1].role": "grand-père",
  "factions[faction-hxh-zoldyck].structure[0].members[2].role": "chef de famille",
  "factions[faction-hxh-zoldyck].structure[1].name": "Enfants",
  "factions[faction-hxh-zoldyck].structure[1].members[2].role": "héritier désigné",
  "factions[faction-hxh-kurta].localizedName": "Clan Kurta",
  "factions[faction-hxh-kurta].description": "Le clan aux Yeux écarlates, massacré par la Brigade fantôme. Kurapika en est le dernier survivant connu.",
  "factions[faction-hxh-kurta].longDescription": "Un peuple isolé dont les yeux deviennent écarlates sous le coup d'une émotion intense, comptés parmi les trésors les plus précieux du monde.",
  "factions[faction-hxh-kakin-royal].localizedName": "Famille royale de Kakin",
  "factions[faction-hxh-kakin-royal].description": "Les quatorze princes de Kakin, qui se disputent la succession au trône pendant le voyage vers le Continent noir.",
  "factions[faction-hxh-phantom-troupe].localizedName": "Brigade fantôme (Genei Ryodan)",
  "factions[faction-hxh-phantom-troupe].description": "Bande de voleurs et de tueurs de classe A originaire de Meteor City. Treize membres marqués d'une araignée.",
  "factions[faction-hxh-phantom-troupe].longDescription": "Fondée et dirigée par Kuroro Lucifer, la Brigade a massacré le clan Kurta pour ses Yeux écarlates. Chaque membre porte un numéro et le tatouage de l'araignée.",
  "factions[faction-hxh-phantom-troupe].structure[0].name": "Chef",
  "factions[faction-hxh-phantom-troupe].structure[0].members[0].role": "n° 0",
  "factions[faction-hxh-phantom-troupe].structure[1].name": "Les douze araignées",
